-- ============================================================================
-- EduROI reference-data seed
-- Generated 2026-11-07 from World Bank, open.er-api, Numbeo and curated sources.
-- Re-runnable: every statement is idempotent.
-- ============================================================================

BEGIN;
SET client_encoding = 'UTF8';

-- Idempotency guards for tables without natural unique constraints.
CREATE UNIQUE INDEX IF NOT EXISTS uq_cost_of_living_country_city_year
    ON cost_of_living (country_id, COALESCE(city, ''), year);
CREATE UNIQUE INDEX IF NOT EXISTS uq_salary_stats_combo
    ON salary_statistics (country_id, major_id, degree_level_id, experience_level, year);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tax_rules_country_bracket_year
    ON tax_rules (country_id, income_bracket_min, year);
CREATE UNIQUE INDEX IF NOT EXISTS uq_loan_rules_country_type
    ON loan_rules (country_id, loan_type);
CREATE UNIQUE INDEX IF NOT EXISTS uq_faqs_page_order
    ON faqs (seo_page_id, display_order);
CREATE UNIQUE INDEX IF NOT EXISTS uq_affiliate_product_name
    ON affiliate_products (name);

-- currencies: 166 rows
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, symbol = EXCLUDED.symbol, exchange_rate_to_usd = EXCLUDED.exchange_rate_to_usd, last_updated = EXCLUDED.last_updated, updated_at = NOW();

-- countries: 209 rows
ON CONFLICT (code) DO UPDATE SET avg_tax_rate = EXCLUDED.avg_tax_rate, gdp_per_capita = EXCLUDED.gdp_per_capita, cost_of_living_index = EXCLUDED.cost_of_living_index, education_quality_index = EXCLUDED.education_quality_index, is_active = TRUE, updated_at = NOW();

-- majors: 70 rows
ON CONFLICT (slug) DO NOTHING;

-- degree_levels: 9 rows
ON CONFLICT (slug) DO NOTHING;

-- universities are inserted through a values table so the country FK can be resolved by code
CREATE TEMP TABLE _seed_university (
    name text, slug text, country_code text, city text, type text, ranking int,
    tuition numeric, currency_code text, acceptance numeric, graduation numeric,
    website text, is_active boolean
) ON COMMIT DROP;


                          currency_code, acceptance_rate, graduation_rate, website_url, is_active, created_at, updated_at)
SELECT s.name, s.slug, c.id, s.city, s.type, s.ranking, s.tuition,
       s.currency_code, s.acceptance, s.graduation, s.website, s.is_active, NOW(), NOW()
FROM _seed_university s JOIN countries c ON c.code = s.country_code
ON CONFLICT (slug) DO NOTHING;

-- cost_of_living is inserted through a values table so the country FK can be resolved by code
CREATE TEMP TABLE _seed_col (
    country_code text, city text, currency_code text, rent numeric, food numeric,
    transport numeric, utilities numeric, other numeric, total numeric, year int
) ON COMMIT DROP;

                             transportation_monthly_avg, utilities_monthly_avg, other_expenses_monthly_avg,
                             total_monthly_avg, year, created_at, updated_at)
SELECT c.id, s.city, s.currency_code, s.rent, s.food, s.transport, s.utilities, s.other,
       s.total, s.year, NOW(), NOW()
FROM _seed_col s JOIN countries c ON c.code = s.country_code
ON CONFLICT DO NOTHING;

-- salary_statistics is inserted through a values table for efficient FK resolution
CREATE TEMP TABLE _seed_salary (
    country_code text, major_slug text, degree_slug text, experience text,
    salary_min numeric, salary_avg numeric, salary_max numeric,
    currency_code text, year int, source text
) ON COMMIT DROP;

                                salary_min, salary_avg, salary_max, currency_code, year, source, created_at, updated_at)
SELECT c.id, m.id, d.id, s.experience, s.salary_min, s.salary_avg, s.salary_max,
       s.currency_code, s.year, s.source, NOW(), NOW()
FROM _seed_salary s
JOIN countries c ON c.code = s.country_code
JOIN majors m ON m.slug = s.major_slug
JOIN degree_levels d ON d.slug = s.degree_slug
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _seed_tax (
    country_code text, bracket_min numeric, bracket_max numeric, tax_rate numeric,
    is_progressive boolean, year int
) ON COMMIT DROP;

SELECT c.id, s.bracket_min, s.bracket_max, s.tax_rate, s.is_progressive, s.year, NOW(), NOW()
FROM _seed_tax s JOIN countries c ON c.code = s.country_code
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _seed_loan (
    country_code text, loan_type text, rate_min numeric, rate_max numeric,
    repayment_years int, grace_months int, is_subsidized boolean
) ON COMMIT DROP;

                         repayment_period_years, grace_period_months, is_subsidized, created_at, updated_at)
SELECT c.id, s.loan_type, s.rate_min, s.rate_max, s.repayment_years, s.grace_months,
       s.is_subsidized, NOW(), NOW()
FROM _seed_loan s JOIN countries c ON c.code = s.country_code
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _seed_program (
    university_slug text, country_code text, degree_slug text, major_slug text,
    tuition numeric, currency_code text, duration numeric, employment numeric,
    grad_salary numeric, is_active boolean
) ON COMMIT DROP;

                                  currency_code, duration_years, employment_rate,
                                  avg_graduate_salary, is_active, created_at, updated_at)
SELECT u.id, m.id, d.id, s.tuition, s.currency_code, s.duration, s.employment,
       s.grad_salary, s.is_active, NOW(), NOW()
FROM _seed_program s
JOIN universities u ON u.slug = s.university_slug
JOIN majors m ON m.slug = s.major_slug
JOIN degree_levels d ON d.slug = s.degree_slug
ON CONFLICT (university_id, major_id, degree_level_id) DO NOTHING;

-- Remove legacy slash-delimited SEO slugs that the /page/:slug route cannot serve.
DELETE FROM faqs WHERE seo_page_id IN (SELECT id FROM seo_pages WHERE slug LIKE '%/%');
DELETE FROM seo_pages WHERE slug LIKE '%/%';

CREATE TEMP TABLE _seed_seo (
    slug text, page_type text, meta_title text, meta_description text, h1_title text,
    country_code text, major_slug text, degree_slug text
) ON COMMIT DROP;

                         country_id, major_id, degree_level_id, default_params,
                         view_count, calculation_count, is_published, created_at, updated_at)
SELECT s.slug, s.page_type, s.meta_title, s.meta_description, s.h1_title,
       'https://eduroi.com/page/' || s.slug, c.id, m.id, d.id,
       jsonb_strip_nulls(jsonb_build_object(
           'countryCode', c.code, 'majorId', m.id, 'degreeLevelId', d.id,
           'tuitionAnnual', round(c.gdp_per_capita * 0.22 * fx.m / 100) * 100,
           'livingCostAnnual', round(CASE WHEN col.total_monthly_avg IS NOT NULL
               THEN col.total_monthly_avg * 12
               ELSE c.gdp_per_capita * 0.3 * fx.m END),
           'durationYears', d.typical_duration_years,
           'expectedSalaryAfter', round(COALESCE(sal.salary_avg, c.gdp_per_capita * fx.m)),
           'currencyCode', fx.cur)),
       0, 0, TRUE, NOW(), NOW()
FROM _seed_seo s
JOIN countries c ON c.code = s.country_code
LEFT JOIN majors m ON m.slug = s.major_slug
LEFT JOIN degree_levels d ON d.slug = s.degree_slug
LEFT JOIN currencies cr ON cr.code = c.currency_code
LEFT JOIN LATERAL (
    SELECT CASE WHEN COALESCE(cr.exchange_rate_to_usd, 1) >= 50000 THEN 1
                ELSE COALESCE(cr.exchange_rate_to_usd, 1) END AS m,
           CASE WHEN COALESCE(cr.exchange_rate_to_usd, 1) >= 50000 THEN 'USD'
                ELSE c.currency_code END AS cur
) fx ON TRUE
LEFT JOIN LATERAL (
    SELECT total_monthly_avg FROM cost_of_living x
    WHERE x.country_id = c.id AND x.city IS NULL AND x.year = 2025
    ORDER BY x.id LIMIT 1
) col ON TRUE
LEFT JOIN LATERAL (
    SELECT ss.salary_avg FROM salary_statistics ss
    WHERE ss.country_id = c.id AND ss.major_id = m.id AND ss.degree_level_id = d.id
    ORDER BY ss.year DESC LIMIT 1
) sal ON TRUE
ON CONFLICT (slug) DO UPDATE SET
    default_params = EXCLUDED.default_params
WHERE seo_pages.default_params IS NULL
   OR seo_pages.default_params ? 'country'
   OR seo_pages.default_params ? 'major'
   OR seo_pages.default_params ? 'degree';

CREATE TEMP TABLE _seed_faq (
    slug text, display_order int, question text, answer text, category text
) ON COMMIT DROP;

SELECT p.id, s.question, s.answer, s.display_order, s.category, NOW(), NOW()
FROM _seed_faq s JOIN seo_pages p ON p.slug = s.slug
ON CONFLICT DO NOTHING;

-- ad_zones: 12 rows
ON CONFLICT (zone_name) DO NOTHING;

CREATE TEMP TABLE _seed_affiliate (
    product_type text, name text, description text, affiliate_url text, commission numeric,
    country_code text, major_slug text, display_priority int, is_active boolean,
    image_url text
) ON COMMIT DROP;

                                  country_id, major_id, display_priority, is_active, image_url,
                                  created_at, updated_at)
SELECT s.product_type, s.name, s.description, s.affiliate_url, s.commission,
       c.id, m.id, s.display_priority, s.is_active, s.image_url, NOW(), NOW()
FROM _seed_affiliate s
LEFT JOIN countries c ON c.code = s.country_code
LEFT JOIN majors m ON m.slug = s.major_slug
ON CONFLICT (name) DO NOTHING;

COMMIT;

-- Summary
SELECT
    (SELECT count(*) FROM countries)          AS countries,
    (SELECT count(*) FROM currencies)         AS currencies,
    (SELECT count(*) FROM majors)             AS majors,
    (SELECT count(*) FROM degree_levels)      AS degree_levels,
    (SELECT count(*) FROM universities)       AS universities,
    (SELECT count(*) FROM university_programs) AS university_programs,
    (SELECT count(*) FROM cost_of_living)     AS cost_of_living,
    (SELECT count(*) FROM salary_statistics)  AS salary_statistics,
    (SELECT count(*) FROM tax_rules)          AS tax_rules,
    (SELECT count(*) FROM loan_rules)         AS loan_rules,
    (SELECT count(*) FROM seo_pages)          AS seo_pages,
    (SELECT count(*) FROM faqs)               AS faqs,
    (SELECT count(*) FROM ad_zones)           AS ad_zones,
    (SELECT count(*) FROM affiliate_products) AS affiliate_products;
