INSERT INTO _seed_faq VALUES
('roi-usa-computer-science', 1, 'How is the ROI for Computer Science in United States calculated?', 'EduROI compares the total cost of a Computer Science degree in United States — tuition, living costs, loan interest and opportunity cost — with the projected lifetime earnings uplift. The result is expressed as net ROI, ROI percentage and break-even years.', 'ROI'),
('roi-usa-computer-science', 2, 'What salary can I expect after studying Computer Science in United States?', 'Graduates of Computer Science programmes in United States typically earn around 141,229 USD per year at the mid-career level. Entry-level pay is usually lower and senior roles can be significantly higher.', 'Salary'),
